// Shared help works for buttons created later by either dashboard script.
const operationHelp={
"project-init":"Create an isolated project. Use when starting a new range project.",
"team-add":"Declare a team network and router. Use when adding a participant team; review an infrastructure plan before deploying.",
"team-remove":"Remove this team from desired state. Use when retiring a team. Applying the resulting plan can delete its infrastructure and interrupt participants.",
"box-add":"Declare a jump box for this team. Use when a user needs remote access to its subnet; review and deploy the declaration afterward.",
"box-remove":"Remove this jump box from desired state. Use when it is no longer needed. Applying the removal deletes the box and interrupts its sessions.",
"scenario-add":"Declare a staging VM from an approved template. Use when building a scenario before staging its changes.",
"container-add":"Declare a staging container from an approved template. Use when adding a lightweight scenario service.",
"network-add":"Declare a custom subnet and router. Use when the scenario needs a separate network.",
"scenario-edit":"Edit this VM’s resources, network, and health checks. Use before staging updated declarations. Applying some changes can restart or replace the VM.",
"container-edit":"Edit this container’s resources, network, and health checks. Use before staging updated declarations. Applying some changes can restart or replace the container.",
"network-edit":"Edit this subnet and router declaration. Use before staging network changes. Applying address or router changes can interrupt connected boxes.",
"scenario-remove":"Remove this VM declaration. Use when retiring a scenario box. Applying its removal deletes the VM and its local data.",
"container-remove":"Remove this container declaration. Use when retiring a scenario box. Applying its removal deletes the container and its local data.",
"network-remove":"Remove this network declaration. Use after moving dependent boxes away. Applying its removal deletes its router and interrupts connectivity.",
"scenario-health":"Run the declared VM health checks. Use after deployment or when diagnosing readiness; the default check is ping.",
"container-health":"Run the declared container health checks. Use after deployment or when diagnosing readiness; the default check is ping.",
"configure-team":"Configure this team’s routers and jump boxes. Use to repair or refresh its managed configuration. Firewall or service updates can briefly interrupt this team’s connections.",
"configure":"Apply managed router or jump-box configuration for the selected project. Use to repair configuration. Firewall or service updates can interrupt project connections.",
"inventory":"Generate automation inventory from current infrastructure. Use before inspecting or running configuration.",
"stage-changes":"Prepare approved local image caches with capacity reservations, then retain a guest deployment plan for review.",
"plan":"Compare desired state with infrastructure and save a reviewable plan. Use after editing declarations and before applying changes.",
"apply":"Apply the reviewed infrastructure plan. Use after checking its changes. Approved deletions or replacements can remove data and interrupt affected machines.",
"stage-deploy":"Apply the reviewed staging plan and configure its resources. Use after staging changes. Changed staging machines or networks can be restarted, replaced, or removed as shown in the plan.",
"release-capture":"Capture staging as an immutable versioned release. Use after validating the scenario. Capture may stop staging machines while creating its images.",
"release-test-prepare":"Create fresh test clones of a captured release. Use before rolling it out to participants.",
"release-test-check":"Run health checks against release test clones. Use after preparing a release test to verify readiness.",
"release-test-cleanup":"Delete the temporary release-test resources. Use after reviewing test results. Test machines and their local data will be removed.",
"release-deploy":"Stage a release rollout for selected teams. Use after a successful release test; review the rollout before applying it.",
"release-upgrade":"Stage an upgrade to a selected release. Use when moving deployed teams to a newer version; review replacement changes before applying.",
"release-rollback":"Stage a return to an earlier release. Use when recovering from a faulty rollout; review its replacement changes before applying.",
"release-apply":"Apply a reviewed release rollout. Use after selecting teams and inspecting its plan. Affected scenario machines can be replaced, interrupting sessions and losing local changes.",
"release-check":"Run readiness checks for a deployed release. Use after rollout or when checking team health.",
"release-show":"View a captured release manifest. Use to inspect its machines, networks, and health checks.",
"guac-sync":"Regenerate Guacamole connection access for this project. Use after changing boxes or their access configuration.",
"guac-users":"Synchronize managed Guacamole users and permissions. Use after editing login or connection access. Revoked access or locked accounts prevent subsequent logins.",
};
const buttonHelp={
"Overview":"View platform status. Use to check the range at a glance.","Projects":"Browse projects. Use to select the environment you want to manage.","CRANGE Users":"Manage dashboard accounts and project roles. Use for dashboard access rather than Guacamole logins.","Jobs":"View queued and completed jobs with their output. Use to follow work or diagnose failures.","Project Overview":"View this project’s infrastructure and controls. Use to inspect or manage project-wide changes.","Teams":"Browse teams, including staging. Use to open a team and manage its boxes.","Scenario":"Build, stage, validate, and release a scenario. Use to prepare changes before deploying them to teams.","Users":"Manage this project’s Guacamole accounts. Use to assign jump boxes and remote access.","Default user":"Set reusable username, password, and jump-box defaults. Use before creating users individually or in bulk.","Project settings":"Open the default user setup. Use to configure defaults for new project users.","Create user":"Create a Guacamole login and optionally its jump-box setup. Use for one participant.","Create multiple users":"Create a numbered batch of Guacamole accounts. Use when participants share a standard setup.","Save default user":"Save username, password, and jump-box defaults. Use when future users should inherit this setup.","Save user":"Save this user’s credentials and access. Use after editing the account. Renaming, locking, or changing credentials can prevent subsequent logins with the old credentials.","Delete selected":"Delete the selected Guacamole accounts. Use for batch account cleanup. These users lose login access; their jump boxes remain.","Delete users":"Confirm removal of the selected accounts. Use after reviewing your selection. Their Guacamole login access will be removed.","Delete user":"Delete this Guacamole account. Use when its access is no longer needed. Login access is removed; assigned jump boxes remain.","Add default jump-box setup":"Declare additional boxes using the saved user setup. Use when this user needs more jump boxes; review and deploy them afterward.","Add jump box to setup":"Add another box to the reusable default setup. Use when each new user needs multiple boxes.","Remove from setup":"Remove this box from the default setup. Use when future users should receive fewer boxes.","Refresh":"Reload current project and job information. Use to see recent changes.","Refresh activity":"Reload this user’s login history and active connections. Use to check current access activity.","Close":"Hide this window. Use when you are finished reading; any background job continues running.","Sign out":"End your dashboard session. Use when finished managing the range.","Sign in":"Start a dashboard session. Use your CRANGE credentials.","← Users":"Return to the project user list. Use to select another account.","← All teams":"Return to the team list. Use to select another team.","Run action":"Submit the action using the entered options. Use after reviewing its settings and any destructive permissions.","Accept staged settings":"Save the reviewed output-only plan. Use when the plan has no infrastructure changes.",
};
function helpForButton(b){const label=b.textContent.trim(),op=b.dataset.helpOperation;if(op==="machine-state"||op==="box-state")return label==="Stop"?"Stop this box. Use for maintenance or testing. Its services and active sessions will be interrupted.":"Start this box. Use when it should be running or when testing startup order.";return operationHelp[op]||buttonHelp[label]||(b.classList.contains("table-link")?`Open ${label}. Use to inspect and manage this entry.`:`${label}. Use to open this control’s settings or details.`)}
const buttonTooltip=el("div",undefined,"button-tooltip");buttonTooltip.id="button-tooltip";buttonTooltip.role="tooltip";buttonTooltip.hidden=true;document.body.append(buttonTooltip);let tooltipButton=null,tooltipTimer;
function hideButtonHelp(){clearTimeout(tooltipTimer);if(tooltipButton)tooltipButton.removeAttribute("aria-describedby");tooltipButton=null;buttonTooltip.hidden=true}
function showButtonHelp(b){hideButtonHelp();tooltipButton=b;tooltipTimer=setTimeout(()=>{if(!b.isConnected)return;buttonTooltip.textContent=helpForButton(b);buttonTooltip.hidden=false;b.setAttribute("aria-describedby",buttonTooltip.id);const r=b.getBoundingClientRect(),w=buttonTooltip.offsetWidth,h=buttonTooltip.offsetHeight;buttonTooltip.style.left=Math.max(8,Math.min(r.left,innerWidth-w-8))+"px";buttonTooltip.style.top=(r.bottom+h+16<innerHeight?r.bottom+8:Math.max(8,r.top-h-8))+"px"},350)}
document.addEventListener("mouseover",e=>{const b=e.target.closest("button");if(b&&b!==tooltipButton)showButtonHelp(b)});
document.addEventListener("mouseout",e=>{if(tooltipButton&&!tooltipButton.contains(e.relatedTarget)&&!buttonTooltip.contains(e.relatedTarget))hideButtonHelp()});
buttonTooltip.addEventListener("mouseleave",hideButtonHelp);
document.addEventListener("focusin",e=>{if(e.target.matches("button"))showButtonHelp(e.target)});document.addEventListener("focusout",hideButtonHelp);document.addEventListener("click",hideButtonHelp);document.addEventListener("keydown",e=>{if(e.key==="Escape")hideButtonHelp()});window.addEventListener("scroll",hideButtonHelp,true);

